import Foundation

/// Debug-only answers in the agent's own shapes, for previews: the contract
/// samples (`work/contract/*.sample.json`, persona Sam on Monday 2026-10-12 at
/// 14:37:05 in UTC−7). No agent, no files, no memory is read. A test holds
/// them equal to the copies in `Tests/UnderstandingFixtures/`.
public struct PreviewUnderstandingReader: UnderstandingReader {
    public enum Scenario: String, Sendable {
        case populated, empty, unavailable, nomodel
        /// Nothing saved yet and no AI tool connected: the first landing.
        case firstDay
    }

    /// The samples' clock and time zone: previews render with these.
    public static let sampleNow = Date(timeIntervalSince1970: 1_791_841_025)
    public static let sampleTimeZone = TimeZone(secondsFromGMT: -25_200)!
    public static let sampleDay = UnderstandingDay(dateLocal: "2026-10-12", tzOffsetSeconds: -25_200)
    /// The samples' calendar: Gregorian, in their time zone.
    public static var sampleCalendar: Calendar {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = sampleTimeZone
        return calendar
    }

    public let scenario: Scenario

    public init(scenario: Scenario = .populated) {
        self.scenario = scenario
    }

    public func overview(_ day: UnderstandingDay) async throws -> DayOverview {
        switch scenario {
        case .unavailable:
            throw UnderstandingError.unavailable
        case .empty:
            return Self.emptyOverview(day)
        case .firstDay:
            var overview = Self.emptyOverview(day)
            overview.aiKnows = AIKnows(recentWork: [], aboutYou: [], hookInstalled: false)
            return overview
        case .populated, .nomodel:
            guard day == Self.sampleDay else { return Self.emptyOverview(day) }
            var overview = try Self.decode(DayOverview.self, PreviewUnderstandingFixtures.overview)
            if scenario == .nomodel {
                overview.modelStatus = Self.modelOff
                overview.account = nil
            }
            return overview
        }
    }

    public func modelPage() async throws -> ModelPage {
        switch scenario {
        case .unavailable:
            throw UnderstandingError.unavailable
        case .populated:
            return try Self.decode(ModelPage.self, PreviewUnderstandingFixtures.modelPage)
        case .empty, .nomodel, .firstDay:
            var page = try Self.decode(ModelPage.self, PreviewUnderstandingFixtures.modelPage)
            page.shared = []
            page.keptBack = []
            page.notSeenLately = []
            if scenario == .nomodel { page.modelStatus = Self.modelOff }
            return page
        }
    }

    public func ask(_ question: String, app: String?, title: String?, now: String?) async throws -> AskAnswer {
        switch scenario {
        case .unavailable:
            throw UnderstandingError.unavailable
        case .empty, .firstDay:
            return AskAnswer(answer: nil, unavailable: nil, sources: [])
        case .populated:
            return try Self.decode(AskAnswer.self, PreviewUnderstandingFixtures.answer)
        case .nomodel:
            let sources = try Self.decode(AskAnswer.self, PreviewUnderstandingFixtures.answer).sources
            return AskAnswer(answer: nil, unavailable: "apple_intelligence_off", sources: sources)
        }
    }

    public func invalidate() async {}
    public func shutdown() async {}

    private static let modelOff = ModelStatus(state: .unavailable, reason: "apple_intelligence_off",
                                              checkedUs: 1_791_839_440_000_000)

    private static func decode<T: Decodable>(_ type: T.Type, _ json: String) throws -> T {
        do {
            return try JSONDecoder().decode(T.self, from: Data(json.utf8))
        } catch {
            throw UnderstandingError.malformed
        }
    }

    /// A day with nothing saved: today when it is the samples' day.
    private static func emptyOverview(_ day: UnderstandingDay) -> DayOverview {
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.timeZone = TimeZone(secondsFromGMT: day.tzOffsetSeconds)
        formatter.dateFormat = "yyyy-MM-dd"
        let start = formatter.date(from: day.dateLocal).map { Int64($0.timeIntervalSince1970) * 1_000_000 } ?? 0
        return DayOverview(
            version: 1, date: day.dateLocal, isToday: day == sampleDay,
            nowUs: Int64(sampleNow.timeIntervalSince1970) * 1_000_000, tzOffsetSecs: day.tzOffsetSeconds,
            dayStartUs: start, dayEndUs: start + 86_400_000_000, basis: .estimated, truncated: false,
            modelStatus: ModelStatus(state: .available, reason: nil, checkedUs: 1_791_839_440_000_000),
            now: .nothing, strip: nil, blocks: [], gaps: [], kinds: [], facts: [], searches: [],
            account: nil, aiKnows: AIKnows(recentWork: [], aboutYou: [], hookInstalled: true)
        )
    }
}

